<?php
namespace App\Policies;
use App\Models\{FinancialCommitment,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class FinancialCommitmentPolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_financial::commitment');} public function view(User $u,FinancialCommitment $r):bool{return $this->canForRecord($u,'view_financial::commitment',$r);} public function create(User $u):bool{return $u->can('create_financial::commitment');} public function update(User $u,FinancialCommitment $r):bool{return $r->status==='draft'&&$this->canForRecord($u,'update_financial::commitment',$r);} public function delete(User $u,FinancialCommitment $r):bool{return $r->status==='draft'&&$this->canForRecord($u,'delete_financial::commitment',$r);} public function deleteAny(User $u):bool{return false;} public function forceDelete(User $u,FinancialCommitment $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function restore(User $u,FinancialCommitment $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function replicate(User $u,FinancialCommitment $r):bool{return false;} public function reorder(User $u):bool{return false;} public function commit(User $u,FinancialCommitment $r):bool{return $this->canForRecord($u,'commit_financial_commitment',$r);} public function release(User $u,FinancialCommitment $r):bool{return $this->canForRecord($u,'release_financial_commitment',$r);} public function cancel(User $u,FinancialCommitment $r):bool{return $this->canForRecord($u,'cancel_financial_commitment',$r);} public function overBudget(User $u,FinancialCommitment $r):bool{return $this->canForRecord($u,'approve_over_budget_commitment',$r);} }
